// Generated by Launchpad (recipe vercel-queue). Launchpad runs this beside
// the app as a background process: it takes each message off the pg-boss
// queue and delivers it to the app's consumer route, as Vercel Queues does,
// with the secret that route answers to. A failed delivery is sent again
// after the time the route's retry rule asks for, until the message expires.

// Each topic and the route that consumes it, from vercel.json.
const ROUTES = [
  {
    "topic": "send-email",
    "path": "/api/queues/send-email"
  }
];

const APP = (process.env.LAUNCHPAD_APP_URL || `http://127.0.0.1:${process.env.PORT || 3000}`).replace(/\/$/, "");
const SECRET = process.env.LAUNCHPAD_QUEUE_SECRET;
// Longer than any request the app is allowed to take.
const DELIVERY_TIMEOUT_MS = 15 * 60 * 1000;

if (!SECRET) {
  console.error("queue-worker: LAUNCHPAD_QUEUE_SECRET is not set");
  process.exit(1);
}

// deliver answers null when the message is done with, and otherwise the
// seconds to wait before sending it again.
async function deliver(route, id, data) {
  const attempt = data.delivery || 1;
  let res;
  let out = {};
  try {
    res = await fetch(APP + route.path, {
      method: "POST",
      headers: {
        "content-type": "application/json",
        "x-launchpad-queue-secret": SECRET,
        "x-launchpad-delivery": JSON.stringify({
          messageId: String(id),
          deliveryCount: attempt,
          createdAt: new Date(data.created || Date.now()).toISOString(),
          expiresAt: new Date(data.expires || Date.now()).toISOString(),
          topicName: route.topic,
          consumerGroup: "default",
        }),
      },
      body: JSON.stringify(data.payload ?? null),
      signal: AbortSignal.timeout(DELIVERY_TIMEOUT_MS),
    });
    out = await res.json().catch(() => ({}));
  } catch (e) {
    console.error(`queue-worker: ${route.topic} ${id} attempt ${attempt}: ${e.message}`);
  }
  if (res && res.ok && out.ok) {
    console.log(`queue-worker: ${route.topic} ${id} delivered on attempt ${attempt}`);
    return null;
  }
  if (out.acknowledge) {
    console.log(`queue-worker: ${route.topic} ${id} dropped on attempt ${attempt}, as its handler asked`);
    return null;
  }
  if (Date.now() > (data.expires || 0)) {
    console.error(`queue-worker: ${route.topic} ${id} expired after ${attempt} attempts`);
    return null;
  }
  const after = out.retry && typeof out.retry.afterSeconds === "number" ? out.retry.afterSeconds : Math.min(300, 5 * 2 ** (attempt - 1));
  console.log(`queue-worker: ${route.topic} ${id} attempt ${attempt} failed (${res ? res.status : "no answer"}); again in ${after}s`);
  return after;
}

const mod = await import("pg-boss");
const PgBoss = mod.PgBoss ?? mod.default ?? mod;
const boss = new PgBoss({ connectionString: process.env.DATABASE_URL, schema: "launchpad_queue" });
boss.on("error", (e) => console.error("queue-worker:", e.message));
await boss.start();
// Messages an earlier version of this change left in pg-boss's default
// schema, moved to this queue's own: now, and every minute after, for any the
// version before sends there while a release is under way.
const { drainOldQueue } = await import("./queue-drain.mjs");
const drain = () => drainOldQueue(boss).catch((e) => console.error("queue-worker: moving old messages:", e.message));
await drain();
setInterval(drain, 60_000);
for (const route of ROUTES) {
  if (boss.createQueue) await boss.createQueue(route.topic, { retryLimit: 5, expireInSeconds: 960 }).catch(() => {});
  await boss.work(route.topic, { batchSize: 1 }, async (jobs) => {
    for (const job of [].concat(jobs)) {
      const again = await deliver(route, job.id, job.data);
      if (again !== null) {
        await boss.send(route.topic, { ...job.data, delivery: (job.data.delivery || 1) + 1 }, { startAfter: again });
      }
    }
  });
}
console.log(`queue-worker: taking ${ROUTES.map((r) => r.topic).join(", ")} from pg-boss, delivering to ${APP}`);

process.on("SIGTERM", async () => {
  await boss.stop({ graceful: true, timeout: 25000 }).catch(() => {});
  process.exit(0);
});

